<?php
namespace App\Services\Curriculum;
use App\Models\CurriculumFragment;use App\Models\CurriculumSource;use App\Models\RepositoryImport;use App\Models\RepositoryImportItem;use App\Models\Subject;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use ZipArchive;
class AcademicRepositoryIngestionService{
 /** Sized for the verified Lesson_Notes archive while retaining ZIP-bomb safeguards. */
 public const MAX_FILES=8000;public const MAX_EXPANDED=3221225472;
 public function ingest(UploadedFile $file,array $meta,int $actor):RepositoryImport{
  $ext=strtolower($file->getClientOriginalExtension());$import=RepositoryImport::create(['filename'=>$file->getClientOriginalName(),'format'=>$ext,'uploaded_by'=>$actor,'status'=>'processing','started_at'=>now()]);
  try{if($ext==='zip')$this->zip($file,$meta,$actor,$import);elseif(in_array($ext,['xlsx','xls'],true))$this->xlsx($file,$meta,$actor,$import);else $this->document($file->getRealPath(),$file->getClientOriginalName(),$file->getMimeType(),$meta,$actor,$import);
   $import->update(['status'=>$import->failed?'completed_with_errors':'completed','completed_at'=>now()]);
  }catch(\Throwable $e){$import->update(['status'=>'failed','failed'=>DB::raw('failed + 1'),'metadata'=>['error'=>Str::limit($e->getMessage(),500)]]);throw $e;}return $import->fresh();
