  $checksum=hash_file('sha256',$path);$duplicate=CurriculumSource::whereNull('tenant_id')->where('checksum',$checksum)->first();if($duplicate){$import->increment('duplicates');$this->item($import,$relative?:$name,'duplicate','Matching checksum already exists.',$duplicate->id);return;}
  [$raw,$locator]=$ext==='docx'?$this->docx($path):($ext==='doc'?$this->doc($path):$this->pdf($path));$meta=$this->infer($relative?:$name,$meta);$clean=$this->clean($raw);$stored=Storage::disk('local')->putFileAs('academic-repository/originals',new \Illuminate\Http\File($path),Str::uuid().'.'.$ext);
